federation/fio-spatial-facilities-in-sta.sparql:
#+ summary: Retrieve all solid waste landfills (NAICS Industry Code 562212) in the state of Georgia (FIPS code 13) and their name and the town they are located in.
#+ tags:
#+   - federation

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX fio: <http://w3id.org/fio/v1/fio#>
PREFIX naics: <http://w3id.org/fio/v1/naics#> 
PREFIX epa-frs: <http://w3id.org/fio/v1/epa-frs#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX spatial: <http://purl.org/spatialai/spatial/spatial-full#>


SELECT * WHERE {
  VALUES ?code {naics:NAICS-562212}
  ?fac rdf:type fio:Facility ;
       fio:ofIndustry ?code ;
       spatial:connectedTo ?town ;
       geo:hasGeometry/geo:asWKT ?facWKT;
       rdfs:label ?facilityName.

  # filter by administrative region (kwgr:administrativeRegion.USA.13 denotes the state of Georgia) and retrieve town
  ?town rdf:type kwg-ont:AdministrativeRegion_3 ;
                   kwg-ont:administrativePartOf+ kwgr:administrativeRegion.USA.13 ;
                   rdfs:label ?townLabel .

  # also retrieve any labels associated with the facility and industry 
  OPTIONAL { ?fac rdfs:label ?faclabel . }
  OPTIONAL { ?code rdfs:label ?ind . }
}

federation/nde-diseases-mondo-parents.sparql:
#+ summary: "Find all diseases in NDE and the Mondo disease parent terms."
#+ tags:
#+   - federation

PREFIX schema: <http://schema.org/>
PREFIX rdfs:   <http://www.w3.org/2000/01/rdf-schema#>
PREFIX obo: <http://purl.obolibrary.org/obo/>

SELECT
  ?disease
  (GROUP_CONCAT(
     DISTINCT REPLACE(STR(?parent),
       "^http://purl\\.obolibrary\\.org/obo/MONDO_", "MONDO:");
     separator=" | "
   ) AS ?directMondoParents)
WHERE {
  {
    SELECT DISTINCT ?disease
    WHERE {
      ?dataset a schema:Dataset ;
               schema:healthCondition ?disease .
      ?disease rdfs:isDefinedBy obo:mondo.owl .
    }
    LIMIT 200
  }

  OPTIONAL {
    ?disease rdfs:subClassOf ?parent .
    ?parent rdfs:isDefinedBy obo:mondo.owl .
  }
}
GROUP BY ?disease
LIMIT 1000

federation/nde-study-mondo-xrefs.sparql:
#+ summary: "Find a study related to influenza and links to other disease sources."
#+ tags:
#+   - ubergraph
#+   - nde

PREFIX schema:   <http://schema.org/>
PREFIX rdf:      <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX oboInOwl: <http://www.geneontology.org/formats/oboInOwl#>

SELECT ?dataset ?datasetName (GROUP_CONCAT(DISTINCT STR(?xref); separator=" | ") AS ?xrefList)
WHERE {
  {
    SELECT ?dataset ?datasetName
    WHERE {
      ?dataset rdf:type schema:Dataset ;
               schema:name ?datasetName ;
               schema:healthCondition <http://purl.obolibrary.org/obo/MONDO_0005812> .
    }
    LIMIT 1
  }

  OPTIONAL {
    <http://purl.obolibrary.org/obo/MONDO_0005812> oboInOwl:hasDbXref ?xref .
  }
}
GROUP BY ?dataset ?datasetName

federation/sawgraph-hydrology-spatial-04.sparql:
#+ summary: Which water bodies are called 'Great Pond' or 'Long Pond' and where are they located?
#+ tags:
#+   - federation

PREFIX hyf: <https://www.opengis.net/def/schema/hy_features/hyf/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX nhdplusv2: <http://nhdplusv2.spatialai.org/v1/nhdplusv2#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema: <https://schema.org/>
PREFIX spatial: <http://purl.org/spatialai/spatial/spatial-full#>

SELECT DISTINCT ?name ?ftype ?county_name WHERE {
  # Select water bodies along with their names, type, and comid
  ?waterbody rdf:type hyf:HY_WaterBody ;
             schema:name ?name ;
             nhdplusv2:hasFTYPE ?ftype ;
             nhdplusv2:hasCOMID ?comid .
  # Keep only water bodies with the desired names
  VALUES ?name { 'Great Pond' 'Long Pond' }
  ?s2cell spatial:connectedTo ?waterbody ;
          rdf:type kwg-ont:S2Cell_Level13 .
  ?county spatial:connectedTo ?s2cell ;
          rdf:type kwg-ont:AdministrativeRegion_2 ;
          rdfs:label ?county_name .
  FILTER regex(str(?county), "datacommons")
} ORDER BY ?name ?county_name

federation/sawgraph-hydrology-spatial_03.sparql:
#+ summary: Find all gravel wells that connect to sand and gravel aquifers in Penobscot County, Maine.
#+ tags:
#+   - federation

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX me_mgs: <http://sawgraph.spatialai.org/v1/me-mgs#>
PREFIX fio: <http://w3id.org/fio/v1/fio#>
PREFIX naics: <http://sawgraph.spatialai.org/v1/fio/naics#>
PREFIX us_frs: <http://sawgraph.spatialai.org/v1/us-frs#>
PREFIX me_mgs_data: <http://sawgraph.spatialai.org/v1/me-mgs-data#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX spatial: <http://purl.org/spatialai/spatial/spatial-full#>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX saw_water: <http://sawgraph.spatialai.org/v1/saw_water#>
PREFIX gwml2: <http://gwml2.org/def/gwml2#>

SELECT DISTINCT ?well ?use ?depth_val ?wellType ?aq ?aqtype WHERE {
  ?well a me_mgs:MGS-Well ;
        me_mgs:hasUse ?use ;
        me_mgs:ofWellType me_mgs_data:d.wellType.Gravel ;
        me_mgs:ofWellType ?wellType ;
        me_mgs:wellDepth ?wellDepth ;
        kwg-ont:sfWithin ?s2neighbor ;
        kwg-ont:sfWithin ?aq_s2 .
  ?wellDepth qudt:numericValue ?depth_val .
  ?s2neighbor spatial:connectedTo kwgr:administrativeRegion.USA.23019.
  ?aq rdf:type gwml2:GW_Aquifer ;
      saw_water:aquiferType ?aqtype ;
      rdf:type gwml2:GW_Aquifer .
  FILTER(?aqtype = 'sand and gravel')
  ?sp_s2 spatial:connectedTo ?aq ;
         rdf:type kwg-ont:S2Cell_Level13 .
  ?aq_s2 spatial:connectedTo ?aq ;
         rdf:type kwg-ont:S2Cell_Level13 .
} ORDER BY ?depth_val
